def get_first_non_bg(row, bg=8):
    for i, v in enumerate(row):
        if v != bg:
            return i
    return -1

def compute_output(row, offset, width=10):
    pattern = list(range(offset, width + offset))  # [offset, offset+1, ..., width-1, 0, 1, ..., offset-1]
    right = [row[p % width] for p in pattern]
    return row + right

